    void UpdateHeading(){string active="";if(currentView=="downloads"){pageTitle.Text="Скачанное";pageNote.Text="Локальные MP3-файлы · папка Музыка\\OldYM";active="Скачанное";}else if(currentView=="wave"){pageTitle.Text="Моя волна";pageNote.Text="Персональные рекомендации";active="Моя волна";}else if(currentView=="likes"){pageTitle.Text="Мне нравится";pageNote.Text="Любимые треки";active="Мне нравится";}else if(currentView=="playlists"||currentView=="playlist"){pageTitle.Text="Плейлисты";pageNote.Text="Твоя музыкальная коллекция";active="Плейлисты";}else if(currentView=="search"){pageTitle.Text="Результаты поиска";pageNote.Text=searchText;}else{pageTitle.Text="Твоя музыка";pageNote.Text="Поиск, любимые треки и моя волна";}foreach(var b in navigation){b.Selected=b.Text==active;b.Invalidate();}}
    void FitColumns(){if(list.Columns.Count!=5)return;int w=Math.Max(260,list.ClientSize.Width-1);list.Columns[2].Width=62;list.Columns[3].Width=34;list.Columns[4].Width=34;int text=w-130;list.Columns[0].Width=(int)(text*0.58);list.Columns[1].Width=text-list.Columns[0].Width;}
    void DrawHeader(object sender,DrawListViewColumnHeaderEventArgs e){using(var b=new SolidBrush(Palette.Background))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header.Text,Font,new Rectangle(e.Bounds.X+10,e.Bounds.Y,e.Bounds.Width-16,e.Bounds.Height),Palette.Muted,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);using(var p=new Pen(Palette.Line))e.Graphics.DrawLine(p,e.Bounds.Left,e.Bounds.Bottom-1,e.Bounds.Right,e.Bounds.Bottom-1);}
    void DrawTrack(object sender,DrawListViewSubItemEventArgs e){Color bg=e.Item.Selected?Palette.Raised:Palette.Background;using(var b=new SolidBrush(bg))e.Graphics.FillRectangle(b,e.Bounds);Track track=e.Item.Tag as Track;bool playing=index>=0&&index<queue.Count&&track!=null&&track.Id==queue[index].Id;if(track!=null&&(e.ColumnIndex==3||e.ColumnIndex==4)){bool active=e.ColumnIndex==3?IsLiked(track):store.IsDownloaded(track);Color actionColor=active?Palette.Accent:Palette.Muted;TextRenderer.DrawText(e.Graphics,e.SubItem.Text,actionFont,e.Bounds,actionColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);return;}Color fg=e.ColumnIndex==0?(playing?Palette.Accent:Palette.Text):Palette.Muted;TextRenderer.DrawText(e.Graphics,e.SubItem.Text,Font,new Rectangle(e.Bounds.X+10,e.Bounds.Y,e.Bounds.Width-16,e.Bounds.Height),fg,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);if(e.Item.Selected&&e.ColumnIndex==0)using(var b=new SolidBrush(Palette.Accent))e.Graphics.FillRectangle(b,e.Bounds.X,e.Bounds.Y+8,2,Math.Max(2,e.Bounds.Height-16));}
    void UI(Action action){if(closing||IsDisposed)return;try{BeginInvoke(new MethodInvoker(delegate{if(!closing)action();}));}catch(InvalidOperationException){}}
    void Report(Exception e){status.Text=e is OperationCanceledException?"Операция отменена":e.Message;}
    bool NeedAccount(){if(api!=null)return false;status.Text="Сначала войди через «Аккаунт»";return true;}
    void Job(Action work,Action success){if(busy){status.Text="Дождись текущего запроса";return;}busy=true;status.Text="Загружаю…";ThreadPool.QueueUserWorkItem(delegate{try{work();UI(delegate{busy=false;success();});}catch(Exception e){UI(delegate{busy=false;Report(e);});}});}
    void SignIn(){using(var dialog=new LoginForm(net)){if(dialog.ShowDialog(this)==DialogResult.OK)Login(dialog.Token,dialog.Remember);}}
    void Login(string token,bool remember){Api candidate=new Api(net,token);List<string> initialLikes=null;Job(delegate{candidate.Account();initialLikes=candidate.LikedIds();if(remember)store.SaveToken(token);else store.Forget();},delegate{Stop();api=candidate;likedIds=initialLikes??new List<string>();screenVersion++;currentView="";currentPlaylist=null;shown.Clear();Render();account.Text=candidate.Login;status.Text="Вход выполнен. Поиск, волна и плейлисты доступны.";});}
    void Search(){if(NeedAccount())return;string text=search.Text.Trim();if(text=="")return;int version=++screenVersion;List<Track> result=null;Job(delegate{result=api.Search(text,0);},delegate{if(version!=screenVersion)return;currentView="search";currentPlaylist=null;searchText=text;page=0;shown=result;Render();more.Text="Показать ещё";more.Enabled=result.Count>0;status.Text="Найдено: "+shown.Count;});}
    void Render(){UpdateHeading();FitColumns();list.BeginUpdate();try{list.Items.Clear();foreach(Track t in shown){var row=new ListViewItem(new[]{t.Title,t.Artist,t.Time,IsLiked(t)?"♥":"♡",downloadingIds.Contains(t.Id)?"…":(store.IsDownloaded(t)?"✓":"↓")});row.Tag=t;list.Items.Add(row);}}finally{list.EndUpdate();}}
    void OpenLikes(){if(NeedAccount())return;int version=++screenVersion;List<string> ids=null;List<Track> tracks=null;Job(delegate{ids=api.LikedIds();tracks=api.Details(ids,0,50);},delegate{if(version!=screenVersion)return;currentView="likes";currentPlaylist=null;likedIds=ids;page=tracks.Count;shown=tracks;Render();more.Text="Показать ещё";more.Enabled=page<ids.Count;status.Text="Мне нравится: "+shown.Count+" / "+ids.Count;});}
    void OpenPlaylists(){if(NeedAccount())return;int version=++screenVersion;List<Playlist> result=null;Job(delegate{result=api.Playlists();},delegate{if(version!=screenVersion)return;DisplayPlaylists(result);status.Text="Открой плейлист двойным щелчком · свои плейлисты можно редактировать";});}
    void DisplayPlaylists(List<Playlist> result){currentView="playlists";currentPlaylist=null;UpdateHeading();playlists=result??new List<Playlist>();shown.Clear();list.BeginUpdate();try{list.Items.Clear();foreach(Playlist p in playlists){var row=new ListViewItem(new[]{p.Title,p.IsOwned?"Мой плейлист":"Плейлист","","", ""});row.Tag=p;list.Items.Add(row);}}finally{list.EndUpdate();}more.Text="Создать плейлист";more.Enabled=true;FitColumns();}
    void ActivateSelected(){if(list.SelectedItems.Count==0)return;var row=list.SelectedItems[0];var p=row.Tag as Playlist;if(p!=null){OpenPlaylist(p);return;}if(!(row.Tag is Track))return;Track selected=row.Tag as Track;if(api==null&&(String.IsNullOrEmpty(selected.LocalPath)||!File.Exists(selected.LocalPath)))return;queue=new List<Track>(shown);waveQueue=currentView=="wave";Play(row.Index);}
    void OpenPlaylist(Playlist playlist){int version=++screenVersion;List<Track> result=null;Job(delegate{result=api.PlaylistTracks(playlist);},delegate{if(version!=screenVersion)return;shown=result;currentView="playlist";currentPlaylist=playlist;Render();more.Text="Показать ещё";more.Enabled=false;status.Text=playlist.Title+" · "+result.Count+" треков";});}
    void OpenWave(){if(NeedAccount())return;int version=++screenVersion;List<Track> result=null;Job(delegate{result=api.WavePreview(18);},delegate{if(version!=screenVersion)return;currentView="wave";currentPlaylist=null;shown=result;Render();more.Text="Показать ещё";more.Enabled=true;status.Text="Моя волна · "+shown.Count+" рекомендаций · двойной щелчок запускает бесконечную очередь";});}
    void OpenDownloaded(){if(store==null)return;++screenVersion;currentView="downloads";currentPlaylist=null;shown=store.DownloadedTracks();page=shown.Count;Render();more.Text="Все скачанные треки";more.Enabled=false;status.Text=shown.Count==0?"Пока нет скачанных треков. Скачанные MP3 появятся здесь.":"Скачанных треков: "+shown.Count+" · двойной щелчок запускает локальный файл.";}
    void LoadMore(){if(NeedAccount())return;if(currentView=="wave"){AppendWave(false);return;}if(shown.Count>=1000){status.Text="В списке уже 1000 треков: уточни поиск";more.Enabled=false;return;}int version=screenVersion;List<Track> result=null;if(currentView=="search")Job(delegate{result=api.Search(searchText,page+1);},delegate{if(version!=screenVersion)return;page++;shown.AddRange(result);Render();more.Enabled=result.Count>0;status.Text="В списке: "+shown.Count;});else if(currentView=="likes")Job(delegate{result=api.Details(likedIds,page,50);},delegate{if(version!=screenVersion)return;page+=Math.Min(50,likedIds.Count-page);shown.AddRange(result);Render();more.Enabled=page<likedIds.Count;status.Text="Мне нравится: "+shown.Count+" / "+likedIds.Count;});}
    void AppendWave(bool forQueue){if(waveBusy||api==null)return;List<Track> target=forQueue?queue:shown;if(target.Count==0)return;string last=target[target.Count-1].Id;int generation=playVersion,version=screenVersion;Api client=api;var sourceQueue=queue;waveBusy=true;ThreadPool.QueueUserWorkItem(delegate{try{List<Track> extra=client.Wave(last);UI(delegate{waveBusy=false;if(api!=client)return;if(forQueue){if(!waveQueue||queue!=sourceQueue)return;int added=AddUnique(queue,extra);if(added==0){status.Text="Волна вернула прежние треки. Нажми «Далее» для повтора.";return;}if(index>20){queue.RemoveRange(0,index-5);index=5;}if(currentView=="wave"){shown=new List<Track>(queue);Render();}if(generation==playVersion&&audio.Mode=="stopped")Play(index+1);}else{if(version!=screenVersion)return;int added=AddUnique(shown,extra);if(shown.Count>200)shown.RemoveRange(0,shown.Count-200);Render();status.Text="Волна: добавлено "+added;}});}catch(Exception e){UI(delegate{waveBusy=false;Report(e);});}});}
    public static int AddUnique(List<Track> target,List<Track> extra){var ids=new HashSet<string>();foreach(var t in target)ids.Add(t.Id);int n=0;foreach(var t in extra)if(ids.Add(t.Id)){target.Add(t);n++;}return n;}
    void Play(int at){
        if(at<0)return;
        if(at>=queue.Count){if(waveQueue){AppendWave(true);status.Text="Подгружаю продолжение волны…";}else status.Text="Конец очереди";return;}
        index=at;Track track=queue[at];int version=Interlocked.Increment(ref playVersion);
        try{audio.Stop();}catch(Exception e){Report(e);}
        seek.Enabled=false;now.Text=track.ToString();time.Text="0:00 / "+track.Time;
        bool localDownload=!String.IsNullOrEmpty(track.LocalPath)&&File.Exists(track.LocalPath);
        if(localDownload&&String.IsNullOrEmpty(track.Cover)){Image old=cover.Image;cover.Image=null;if(old!=null)old.Dispose();cover.Invalidate();}else LoadCover(track,version);
        status.Text=localDownload?"Открываю скачанный MP3…":"Загружаю MP3 в дисковый кэш…";
        Api client=api;
        ThreadPool.QueueUserWorkItem(delegate{
            try{
                string path=localDownload?track.LocalPath:store.AudioPath(track);
                if(!localDownload){if(client==null)throw new IOException("Для потокового воспроизведения войди в аккаунт. Локальный файл недоступен.");if(!File.Exists(path))net.Download(client.Audio(track),path,delegate{return closing||version!=playVersion;});if(closing||version!=playVersion)return;store.Trim(path);}
                if(closing||version!=playVersion)return;
                UI(delegate{if(version!=playVersion)return;try{audio.Open(path);pause.Text="Пауза";seek.Enabled=true;status.Text="Играет: "+track.Title;if(waveQueue&&queue.Count-index<=3)AppendWave(true);}catch(Exception e){Report(e);}});
            }catch(Exception e){UI(delegate{if(version==playVersion)Report(e);});}
        });
    }
    void LoadCover(Track track,int version){Image old=cover.Image;cover.Image=null;if(old!=null)old.Dispose();cover.Invalidate();ThreadPool.QueueUserWorkItem(delegate{try{Track full=track;if(String.IsNullOrEmpty(full.Cover)){Api client=api;if(client!=null){var details=client.Details(new List<string>{track.Id},0,1);if(details.Count>0)full=details[0];}}string url=full.CoverUrl(200);if(url==null)throw new IOException("API не прислал адрес обложки");byte[] bytes=net.Bytes(url,null,null,2*1024*1024);Bitmap resized;using(var stream=new MemoryStream(bytes))using(var image=Image.FromStream(stream)){if(image.Width>2048||image.Height>2048)throw new IOException("Слишком большая обложка");resized=new Bitmap(128,128);using(var g=Graphics.FromImage(resized)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.Clear(Palette.Raised);double scale=Math.Min(128.0/image.Width,128.0/image.Height);int w=(int)(image.Width*scale),h=(int)(image.Height*scale);g.DrawImage(image,(128-w)/2,(128-h)/2,w,h);}}if(closing){resized.Dispose();return;}UI(delegate{if(version!=playVersion){resized.Dispose();return;}Image prior=cover.Image;cover.Image=resized;if(prior!=null)prior.Dispose();cover.Invalidate();});}catch(Exception e){UI(delegate{if(version==playVersion)status.Text="Обложка: "+e.Message;});}});}
    void Stop(){Interlocked.Increment(ref playVersion);waveQueue=false;try{audio.Stop();}catch(Exception e){Report(e);}seek.Enabled=false;seek.Value=0;pause.Text="Пауза";status.Text="Остановлено";}
    void TickPlayer(){if(!AudioPlayer.IsWindows)return;try{string mode=audio.Mode;if(mode=="closed")return;int length=audio.Length,position=audio.Position;time.Text=FormatTime(position)+" / "+FormatTime(length);if(!seeking&&length>0)seek.Value=Math.Min(1000,(int)(position*1000L/length));if(mode=="stopped"&&length>0&&position>=length-500){if(index+1<queue.Count)Play(index+1);else if(waveQueue)AppendWave(true);else Stop();}}catch(Exception e){Report(e);}}
    static string FormatTime(int ms){return String.Format("{0}:{1:00}",ms/60000,(ms/1000)%60);}
    bool IsLiked(Track track){return track!=null&&likedIds!=null&&likedIds.Contains(track.Id);}
    void ToggleLike(Track track){if(NeedAccount()||track==null)return;bool wasLiked=IsLiked(track);Job(delegate{if(wasLiked)api.Unlike(track);else api.Like(track);},delegate{if(wasLiked)likedIds.Remove(track.Id);else if(!likedIds.Contains(track.Id))likedIds.Insert(0,track.Id);if(currentView=="likes"&&wasLiked){shown.RemoveAll(delegate(Track x){return x.Id==track.Id;});page=Math.Max(0,page-1);Render();more.Enabled=page<likedIds.Count;status.Text="Убрано из избранного: "+track.Title;}else{Render();status.Text=wasLiked?"Убрано из избранного: "+track.Title:"Добавлено в избранное: "+track.Title;}});}
    void LikeSelected(){if(list.SelectedItems.Count==0)return;ToggleLike(list.SelectedItems[0].Tag as Track);}
    void DownloadSelected(){if(list.SelectedItems.Count==0)return;DownloadTrack(list.SelectedItems[0].Tag as Track);}
    void DownloadTrack(Track track){if(NeedAccount()||track==null)return;string target=store.DownloadPath(track);if(File.Exists(target)){try{Process.Start("explorer.exe","/select,\""+target+"\"");}catch(Exception e){status.Text="Файл уже скачан: "+target+" · "+e.Message;}return;}if(downloadingIds.Contains(track.Id))return;downloadingIds.Add(track.Id);Render();status.Text="Скачиваю: "+track.Title;Api client=api;ThreadPool.QueueUserWorkItem(delegate{Exception failure=null;try{string url=client.Audio(track);if(closing||api!=client)throw new OperationCanceledException();net.Download(url,target,delegate{return closing||api!=client;});store.SaveDownloadInfo(track,target);}catch(Exception e){failure=e;}UI(delegate{downloadingIds.Remove(track.Id);Render();if(failure!=null)Report(failure);else{status.Text="Скачано: "+track.Title+" · "+target;if(currentView=="downloads")OpenDownloaded();}});});}
    void AddSelectedToPlaylist(){if(list.SelectedItems.Count==0)return;AddTrackToPlaylist(list.SelectedItems[0].Tag as Track);}
    void AddTrackToPlaylist(Track track){if(NeedAccount()||track==null)return;if(playlists.Count==0){List<Playlist> result=null;Job(delegate{result=api.Playlists();},delegate{playlists=result;ChoosePlaylistAndAdd(track);});}else ChoosePlaylistAndAdd(track);}
    void ChoosePlaylistAndAdd(Track track){var owned=new List<Playlist>();foreach(Playlist p in playlists)if(p.IsOwned)owned.Add(p);if(owned.Count==0){status.Text="Нет собственных плейлистов. Создай плейлист в разделе «Плейлисты».";return;}Playlist chosen=PickPlaylist(owned);if(chosen==null)return;Job(delegate{api.AddTrackToPlaylist(chosen,track);},delegate{status.Text="Добавлено в плейлист «"+chosen.Title+"»: "+track.Title;if(currentView=="playlist"&&currentPlaylist!=null&&currentPlaylist.Kind==chosen.Kind&&currentPlaylist.Owner==chosen.Owner)OpenPlaylist(chosen);});}
    void RemoveSelectedFromPlaylist(){if(NeedAccount()||currentPlaylist==null||!currentPlaylist.IsOwned||list.SelectedItems.Count==0)return;int position=list.SelectedIndices[0];Track track=list.SelectedItems[0].Tag as Track;if(track==null)return;if(MessageBox.Show(this,"Убрать «"+track.Title+"» из плейлиста «"+currentPlaylist.Title+"»?","OldYM",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Playlist playlist=currentPlaylist;Job(delegate{api.RemoveTrackFromPlaylist(playlist,position);},delegate{status.Text="Трек удалён из плейлиста";OpenPlaylist(playlist);});}
    void CreatePlaylist(){if(NeedAccount())return;string title=AskText("Новый плейлист","Название плейлиста","");if(String.IsNullOrWhiteSpace(title))return;List<Playlist> updated=null;Job(delegate{api.CreatePlaylist(title);updated=api.Playlists();},delegate{DisplayPlaylists(updated);status.Text="Плейлист создан: "+title.Trim();});}
    void RenameSelectedPlaylist(){if(NeedAccount()||list.SelectedItems.Count==0)return;Playlist playlist=list.SelectedItems[0].Tag as Playlist;if(playlist==null||!playlist.IsOwned)return;string title=AskText("Переименовать плейлист","Новое название",playlist.Title);if(String.IsNullOrWhiteSpace(title))return;List<Playlist> updated=null;Job(delegate{api.RenamePlaylist(playlist,title);updated=api.Playlists();},delegate{DisplayPlaylists(updated);status.Text="Плейлист переименован";});}
    void DeleteSelectedPlaylist(){if(NeedAccount()||list.SelectedItems.Count==0)return;Playlist playlist=list.SelectedItems[0].Tag as Playlist;if(playlist==null||!playlist.IsOwned)return;if(MessageBox.Show(this,"Удалить плейлист «"+playlist.Title+"»? Это действие нельзя отменить.","OldYM",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;List<Playlist> updated=null;Job(delegate{api.DeletePlaylist(playlist);updated=api.Playlists();},delegate{DisplayPlaylists(updated);status.Text="Плейлист удалён";});}
    string AskText(string title,string prompt,string initial){using(Form dialog=new Form()){dialog.Text=title;dialog.ClientSize=new Size(360,138);dialog.FormBorderStyle=FormBorderStyle.FixedDialog;dialog.StartPosition=FormStartPosition.CenterParent;dialog.MaximizeBox=false;dialog.MinimizeBox=false;var label=new Label{Text=prompt,Left=14,Top=12,Width=330,Height=22};var input=new TextBox{Left=14,Top=40,Width=330,Text=initial??""};var ok=new Button{Text="Сохранить",Left=166,Top=84,Width=84,DialogResult=DialogResult.OK};var cancel=new Button{Text="Отмена",Left=260,Top=84,Width=84,DialogResult=DialogResult.Cancel};dialog.Controls.Add(label);dialog.Controls.Add(input);dialog.Controls.Add(ok);dialog.Controls.Add(cancel);dialog.AcceptButton=ok;dialog.CancelButton=cancel;dialog.Shown+=delegate{input.Focus();input.SelectAll();};return dialog.ShowDialog(this)==DialogResult.OK?input.Text.Trim():null;}}
    Playlist PickPlaylist(List<Playlist> choices){using(Form dialog=new Form()){dialog.Text="Добавить в плейлист";dialog.ClientSize=new Size(360,132);dialog.FormBorderStyle=FormBorderStyle.FixedDialog;dialog.StartPosition=FormStartPosition.CenterParent;dialog.MaximizeBox=false;dialog.MinimizeBox=false;var label=new Label{Text="Выбери свой плейлист:",Left=14,Top=12,Width=330,Height=22};var combo=new ComboBox{Left=14,Top=38,Width=330,DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="Title"};combo.DataSource=choices;var ok=new Button{Text="Добавить",Left=166,Top=82,Width=84,DialogResult=DialogResult.OK};var cancel=new Button{Text="Отмена",Left=260,Top=82,Width=84,DialogResult=DialogResult.Cancel};dialog.Controls.Add(label);dialog.Controls.Add(combo);dialog.Controls.Add(ok);dialog.Controls.Add(cancel);dialog.AcceptButton=ok;dialog.CancelButton=cancel;return dialog.ShowDialog(this)==DialogResult.OK?combo.SelectedItem as Playlist:null;}}
    void About(){using(var f=new AboutForm())f.ShowDialog(this);}
    void Demo(){currentView="demo";account.Text="Просмотр интерфейса\nБез входа и сети";shown=Api.Tracks(Json.Parse("[{\"id\":\"1\",\"title\":\"Пример композиции\",\"durationMs\":198000,\"artists\":[{\"name\":\"Исполнитель\"}]},{\"id\":\"2\",\"title\":\"Ещё один трек\",\"durationMs\":245000,\"artists\":[{\"name\":\"Другой исполнитель\"}]}]"));Render();status.Text="Демонстрационный режим: без авторизации и воспроизведения";}
}
public sealed class LoginForm : Form {
    readonly Net net;readonly TextBox token=new TextBox(),code=new TextBox(),url=new TextBox();readonly Label state=new Label();readonly CheckBox remember=new CheckBox();readonly Button device=new Button(),accept=new Button();
    System.Threading.Timer poll;volatile bool stopped;int polling,interval=5;DateTime expires;string deviceCode;
    public string Token{get;private set;}public bool Remember{get{return remember.Checked;}}
    public LoginForm(Net n){net=n;Text="Вход в Яндекс";ClientSize=new Size(500,355);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;Font=new Font("Tahoma",9);
        var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=9,Padding=new Padding(12)};Controls.Add(panel);panel.Controls.Add(new Label{Text="Подтверди код на сайте Яндекса — можно с телефона",AutoSize=true});device.Text="Получить код входа";device.AutoSize=true;device.Click+=delegate{Request();};panel.Controls.Add(device);code.ReadOnly=true;code.Font=new Font("Tahoma",17,FontStyle.Bold);code.Dock=DockStyle.Top;panel.Controls.Add(code);url.ReadOnly=true;url.Dock=DockStyle.Top;url.DoubleClick+=delegate{if(url.Text!="")try{Process.Start(url.Text);}catch{}};panel.Controls.Add(url);state.Text="Адрес можно скопировать; двойной щелчок открывает браузер";state.Size=new Size(465,40);panel.Controls.Add(state);
        panel.Controls.Add(new Label{Text="Или вставь свой OAuth-токен Яндекс Музыки",AutoSize=true});token.UseSystemPasswordChar=true;token.Dock=DockStyle.Top;panel.Controls.Add(token);remember.Text="Сохранить вход для текущего пользователя Windows";remember.Checked=true;remember.AutoSize=true;panel.Controls.Add(remember);accept.Text="Войти с токеном";accept.AutoSize=true;accept.Click+=delegate{if(token.Text.Trim().Length==0)return;Token=token.Text.Trim();DialogResult=DialogResult.OK;Close();};panel.Controls.Add(accept);FormClosed+=delegate{stopped=true;if(poll!=null)poll.Dispose();};Theme(this);
    }
    static void Theme(Control c){c.BackColor=c is TextBox?Palette.Raised:Palette.Background;c.ForeColor=Palette.Text;var b=c as Button;if(b!=null){b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Palette.Line;b.BackColor=Palette.Raised;b.Padding=new Padding(8,3,8,3);}foreach(Control child in c.Controls)Theme(child);}
    void UI(Action action){if(stopped||IsDisposed)return;try{BeginInvoke(new MethodInvoker(delegate{if(!stopped)action();}));}catch(InvalidOperationException){}}
    void Request(){device.Enabled=false;state.Text="Получаю код…";ThreadPool.QueueUserWorkItem(delegate{try{var auth=new DeviceAuth(net);object d=auth.Request();string address=DeviceAuth.VerificationUrl(d);deviceCode=Json.Str(d,"device_code","");if(deviceCode=="")throw new IOException("Сервис не прислал код устройства");interval=Math.Max(3,Json.Int(d,"interval",5));expires=DateTime.UtcNow.AddSeconds(Math.Min(1800,Json.Int(d,"expires_in",600)));UI(delegate{code.Text=Json.Str(d,"user_code","");url.Text=address;state.Text="Введи код на странице Яндекса. Ожидаю подтверждения…";poll=new System.Threading.Timer(delegate{Poll(auth);},null,interval*1000,interval*1000);});}catch(Exception e){UI(delegate{state.Text=e.Message;device.Enabled=true;});}});}
    void Poll(DeviceAuth auth){if(stopped||Interlocked.Exchange(ref polling,1)==1)return;try{if(DateTime.UtcNow>=expires)throw new IOException("Код истёк. Получи новый код.");object d=auth.Poll(deviceCode);string access=Json.Str(d,"access_token","");if(access!=""){UI(delegate{Token=access;DialogResult=DialogResult.OK;Close();});return;}string error=Json.Str(d,"error","");if(error=="slow_down"){interval+=5;if(!stopped)poll.Change(interval*1000,interval*1000);}else if(error!="authorization_pending")throw new IOException("Авторизация: "+error);}catch(Exception e){if(poll!=null)poll.Dispose();UI(delegate{state.Text=e.Message;device.Enabled=true;});}finally{Interlocked.Exchange(ref polling,0);}}
}
